changeSet.sql:
CREATE TABLE account ( id uuid DEFAULT gen_random_uuid() PRIMARY KEY, email varchar NOT NULL, name varchar NOT NULL, encoded_password varchar NOT NULL, status account_status_domain NOT NULL DEFAULT 'CREATED', created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
UNIQUE(email) );
CREATE TABLE application ( id bigserial PRIMARY KEY, name varchar NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE role ( id bigserial PRIMARY KEY, name varchar NOT NULL, app_id bigint NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT fk_app FOREIGN KEY(app_id) REFERENCES application(id), UNIQUE(name, app_id) );
CREATE TABLE account2role ( account_id uuid NOT NULL, role_id bigint NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT fk_account FOREIGN KEY(account_id) REFERENCES account(id), CONSTRAINT fk_role FOREIGN KEY(role_id) REFERENCES role(id), UNIQUE(account_id, role_id) );
CREATE TABLE refresh_token ( id uuid DEFAULT gen_random_uuid() PRIMARY KEY, account_id uuid NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at timestamp with time zone NOT NULL,
CONSTRAINT fk_account FOREIGN KEY(account_id) REFERENCES account(id), UNIQUE(account_id) );
INSERT INTO application (id, name) VALUES (1, 'any'), (2, 'bg-order'), (3, 'translator'), (4, 'brating'), (5, 'memory-deluge');
INSERT INTO role (id, name, app_id) VALUES (1, 'admin', 1), (2, 'user', 1);

ALTER TABLE account ADD COLUMN password_changed_at timestamp with time zone NULL;

CREATE TABLE password_reset_token (
	id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
	account_id uuid NOT NULL,
	created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
	expires_at timestamp with time zone NOT NULL,

	CONSTRAINT fk_password_reset_token_account FOREIGN KEY(account_id) REFERENCES account(id)
);

CREATE INDEX idx_password_reset_token_account ON password_reset_token(account_id);

SELECT setval(
	'application_id_seq',
	(SELECT COALESCE(MAX(id), 1) FROM application),
	(SELECT MAX(id) FROM application) IS NOT NULL
);

SELECT setval(
	'role_id_seq',
	(SELECT COALESCE(MAX(id), 1) FROM role),
	(SELECT MAX(id) FROM role) IS NOT NULL
);

CREATE TABLE account_security_event (
	id bigserial PRIMARY KEY,
	account_id uuid NOT NULL,
	type varchar(32) NOT NULL,
	ip varchar(45) NULL,
	user_agent varchar(512) NULL,
	created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,

	CONSTRAINT fk_account_security_event_account FOREIGN KEY(account_id) REFERENCES account(id)
);

CREATE INDEX idx_account_security_event_account_created
	ON account_security_event(account_id, created_at DESC);

CREATE TABLE failed_login_attempt (
	id bigserial PRIMARY KEY,
	email varchar NOT NULL,
	ip varchar(45) NULL,
	user_agent varchar(512) NULL,
	created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_failed_login_attempt_created
	ON failed_login_attempt(created_at DESC);
